import fs from "fs";
import path from "path";

function walk(dir, files = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, files);
    else if (entry.name.endsWith(".ts") || entry.name.endsWith(".html")) files.push(full);
  }
  return files;
}

const files = walk("src");
const names = ["fancyRef", "fancy", "firstPill", "pill"];
let totalEdits = 0;
let touchedFiles = 0;

for (const file of files) {
  let content = fs.readFileSync(file, "utf8");
  let edits = 0;
  for (const name of names) {
    const re = new RegExp(`\\b${name}\\b((?:\\(\\))?\\??)\\.disableTooltip\\(`, "g");
    content = content.replace(re, (match, suffix) => {
      edits++;
      return `${name}${suffix}.hideHint(`;
    });
  }
  if (edits > 0) {
    fs.writeFileSync(file, content, "utf8");
    totalEdits += edits;
    touchedFiles++;
    console.log(`${file}: ${edits}`);
  }
}
console.log(`Total: ${totalEdits} edits in ${touchedFiles} files`);
EOF
